// Browser artifacts are committed for static hosting. Edit the Edge sources only.
const root = new URL("../", import.meta.url);
const sources = ["game-rules.ts", "manna.js"];
export async function syncGame(check = false) {
  for (const name of sources) {
    const source = new URL(`supabase/functions/game-mcp/${name}`, root);
    const target = new URL(
      `src/js/config/${name.replace(/\.ts$/, ".js")}`,
      root,
    );
    const content =
      "// GENERATED by scripts/sync-game.ts; edit supabase/functions/game-mcp/ instead.\n" +
      (await Deno.readTextFile(source)).replaceAll(
        '"./game-rules.ts"',
        '"./game-rules.js"',
      )
        .replaceAll(/\s+as const\b/g, "").replaceAll("\r\n", "\n");
    const current = await Deno.readTextFile(target).catch(() => "");
    if (current.replaceAll("\r\n", "\n") === content) continue;
    if (check) {
      throw new Error(
        `Stale browser artifact: ${target.pathname}. Run scripts/sync-game.ts.`,
      );
    }
    await Deno.writeTextFile(target, content);
  }
}
if (import.meta.main) {
  await syncGame(Deno.args.includes("--check"));
  console.log(
    "PASS: browser game rules and engine match the authoritative Edge sources.",
  );
}
